```

A migration is then merged that drops the unique index, because it 'duplicated an application check'. What does this test do?

solution.code:
function truncationOrder(tables) {
  const names = [];
  const dependsOn = {};
  const dependantCount = {};
  for (const table of tables) {
    names.push(table.name);
    dependsOn[table.name] = table.dependsOn.slice();
    dependantCount[table.name] = 0;
  }
  for (const name of names) {
    for (const parent of dependsOn[name]) {
      if (dependantCount[parent] !== undefined) {
        dependantCount[parent] += 1;
      }
    }
  }

  const order = [];
  const emitted = {};
  let progress = true;
  while (order.length !== names.length && progress) {
    const ready = [];
    for (const name of names) {
      if (!emitted[name] && dependantCount[name] === 0) {
        ready.push(name);
      }
    }
    ready.sort();
    progress = ready.length > 0;
    for (const name of ready) {
      emitted[name] = true;
      order.push(name);
      for (const parent of dependsOn[name]) {
        if (dependantCount[parent] !== undefined) {
          dependantCount[parent] -= 1;
        }
      }
    }
  }

  const remaining = [];
  for (const name of names) {
    if (!emitted[name]) {
      remaining.push(name);
    }
  }
  remaining.sort();
  return order.concat(remaining);
}

