solution.code:
function stubFor(request, stubs) {
  function segmentsOf(path) {
    const parts = [];
    for (const part of path.split('/')) {
      if (part !== '') {
        parts.push(part);
      }
    }
    return parts;
  }

  const requestParts = segmentsOf(request.path);
  for (const stub of stubs) {
    if (stub.method !== request.method) {
      continue;
    }
    const stubParts = segmentsOf(stub.path);
    if (stubParts.length !== requestParts.length) {
      continue;
    }
    let matched = true;
    for (let i = 0; i < stubParts.length; i += 1) {
      const expected = stubParts[i];
      if (expected.charAt(0) === ':') {
        continue;
      }
      if (expected !== requestParts[i]) {
        matched = false;
        break;
      }
    }
    if (matched) {
      return stub.response;
    }
  }
  return null;
}

grading.starterCode:
function stubFor(request, stubs) {
  // Exact string match only: parameter stubs never match anything.
  for (const stub of stubs) {
    if (stub.method === request.method && stub.path === request.path) {
      return stub.response;
    }
  }
  return null;
}

