This test is offered as evidence that Ashgrove handles a provider timeout.

```js
test('a provider timeout does not create a refund', async () => {
  const provider = {
    refunds: { create: async () => ({ id: 'rf_1', status: 'succeeded' }) },
    charges: { create: async () => { throw new TimeoutError(); } },
  };

  await expect(issueRefund(provider, { ticketId: 't-1' })).resolves.toBeDefined();
  expect(await refunds.count()).toBe(1);
});
```

`issueRefund` calls only `provider.refunds.create`. What is the problem, and what would you do before trusting any test like this?

solution.code:
function scriptedOutcome(script, callIndex) {
  let consumed = 0;
  let lastOutcome = 'ok';
  let sawEntry = false;
  for (const step of script) {
    if (step.times <= 0) {
      continue;
    }
    sawEntry = true;
    lastOutcome = step.outcome;
    if (callIndex < consumed + step.times) {
      return step.outcome;
    }
    consumed += step.times;
  }
  return sawEntry ? lastOutcome : 'ok';
}

grading.starterCode:
function scriptedOutcome(script, callIndex) {
  // Treats each entry as exactly one call and ignores `times`.
  const step = script[callIndex];
  return step ? step.outcome : 'ok';
}
